def apply(inputs, premises):
    checked = []
    personal_used = False
    carryon_used = False
    for i in range(len(inputs["lengths"])):
        fits_personal = inputs["lengths"][i] <= inputs["personal_limits"][0] and inputs["widths"][i] <= inputs["personal_limits"][1] and inputs["heights"][i] <= inputs["personal_limits"][2]
        fits_carryon = inputs["lengths"][i] <= inputs["carryon_limits"][0] and inputs["widths"][i] <= inputs["carryon_limits"][1] and inputs["heights"][i] <= inputs["carryon_limits"][2]
        if fits_personal and not personal_used:
            personal_used = True
        elif fits_carryon and not carryon_used:
            carryon_used = True
        else:
            checked = checked + [i]
    fees = 0
    for position in range(len(checked)):
        if position == 0:
            fees = fees + inputs["first_checked_fee"]
        elif position == 1:
            fees = fees + inputs["second_checked_fee"]
        elif position == 2:
            fees = fees + inputs["third_checked_fee"]
        else:
            fees = fees + inputs["fourth_plus_checked_fee"]
        item = checked[position]
        weight_fee = 0
        if inputs["weights"][item] > inputs["cabin_standard_weight_limit"]:
            for j in range(len(inputs["overweight_upper_bounds"])):
                if inputs["weights"][item] <= inputs["overweight_upper_bounds"][j]:
                    weight_fee = inputs["overweight_fees"][j]
                    break
        dimension = inputs["lengths"][item] + inputs["widths"][item] + inputs["heights"][item]
        size_fee = 0
        for j in range(len(inputs["size_upper_bounds"])):
            if dimension <= inputs["size_upper_bounds"][j]:
                size_fee = inputs["size_fees"][j]
                break
        fees = fees + max(weight_fee, size_fee)
    return {"answer": int(inputs["ticket_price"] + fees)}

def apply(inputs, premises):
    answer = {}
    combined_limit = premises["individual_residual_limit"] * inputs["debtor_count"]
    for i in range(len(inputs["asset_descriptions"])):
        claims = []
        if inputs["qualifies_as_residual_personal_property"][i]:
            if inputs["include_claim_values"]:
                claim_value = min(inputs["asset_values"][i], combined_limit)
                claims = [{"citation": premises["residual_citation"], "claim_value": claim_value}]
            else:
                claims = [premises["residual_citation"]]
        answer[inputs["asset_descriptions"][i]] = claims
    return {"answer": answer}
